head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS20011.xml';
scwin.objParam = new Object();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.MKTACT_TP_CD = arrPar[0].MKTACT_TP_CD;
        scwin.objParam.BND_APPL_ID = arrPar[0].BND_APPL_ID;
        if (arrPar[0].BND_LIST_PROCS_TP_CD == undefined || arrPar[0].BND_LIST_PROCS_TP_CD == '') {
            scwin.objParam.BND_LIST_PROCS_TP_CD = '1';
        } else {
            scwin.objParam.BND_LIST_PROCS_TP_CD = arrPar[0].BND_LIST_PROCS_TP_CD;
        }
    }
};




/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권상장수수료면제사유코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    $c.bns.fn_SetBnsCombo1(scwin.vScrenID, dts_ListFeeExamptFsnCd, '03385', 6);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(txb_IsuNm) == '') {
        $c.win.alert("등록할 데이타가 없습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == '') {
        $c.win.alert("[상장수수료 납부여부]를 선택하십시오.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == "E" && $c.stf.getObjectValue(cmb_BndListFeeExmptRsnCd) == '') {
        $c.win.alert("상장수수료 면제시에는 면제사유를 선택하십시오.");
        return false;
    }

    //면제가 아닐경우, 입금일 체크
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) != "E") {
        if ($c.stf.getObjectValue(edt_FeeDepoDd) == '') {
            $c.win.alert("상장수수료 면제가 아닌 경우, 입금일을 입력하십시오.");
            return false;
        }
        if ($c.stf.getObjectValue(edt_FeeDepoDd) > scwin.vCurDate) {
            $c.win.alert("입금일은 오늘 이후 날짜를 입력하실 수 없습니다.");
            return false;
        }
    }
    if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '비고(사유)')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자')) return false;
    return true;
};


/********************************************** 
 * 함수명   : fn_Update
 * 설명      : 상장수수료 및 연부과금에서  저장 시, 수정처리
 ***********************************************/
scwin.fn_Update = function() {
    //변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    var url = "/bns/IsuChgAmt.do?method=updateAddListFee";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SaveAuto
 * 설명       : 면제시 자동 등록한다.
 ***********************************************/
scwin.fn_SaveAuto = async function() {
    //바인딩 되지 않은 컴포넌트 데이터셋에 셋팅
    dts_DtlInfo.setCellData(1, "BND_APPL_ID", scwin.objParam.BND_APPL_ID);
    if (scwin.objParam.MKTACT_TP_CD == '305') {
        var prt = $c.frame.path("../");
        prt.dts_AddListFee.ImportData(dts_DtlInfo.getRangeJSON(1, dts_DtlInfo.getTotalRow(), false));
        var arrPar = new Array();
        arrPar[0] = {
            REG_YN: "Y"
        };
        scwin.fn_SetPar(arrPar);
        await $c.frame.CloseFrame();
    } else if (scwin.objParam.MKTACT_TP_CD == '') {
        scwin.fn_Update();
    }
};
scwin.gform_onload = function() {
    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Input);

    //호출파라미터설정
    scwin.fn_SetParam();
    //면제사유코드
    scwin.fn_SetComboCode();

    //상장수수료 면제사유 비활성화
    cmb_BndListFeeExmptRsnCd.setDisabled(true);

    //추가상장 수수료등록 조회
    var dsNm = 'BNS_ADD_ANULFEE_INSERT_INFO';
    var qryId;
    var param;
    if (scwin.objParam.MKTACT_TP_CD == '305') {
        qryId = 'lds.stf.bnsisuchg.select.selectAddBndListFee';
    } else if (scwin.objParam.MKTACT_TP_CD == '') {
        qryId = 'lds.stf.bnsisuchg.select.selectAddBndListFeeOrAnulFee';
    }
    param += '&{P}V_MKTACT_TP_CD=' + scwin.objParam.MKTACT_TP_CD;
    param += '&{P}V_BND_APPL_ID=' + scwin.objParam.BND_APPL_ID;
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.objParam.BND_LIST_PROCS_TP_CD;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};
scwin.dts_DtlInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    //담당자명이 비어 있는 경우, 사용자 이름을 보여줌
    if ($c.stf.getObjectValue(txb_ChrgNm) == '') {
        $c.stf.setObjectValue(txb_ChrgNm, js_emp_nm);
    }
    if (scwin.objParam.MKTACT_TP_CD != '') {
        //자동저장
        if ($c.stf.getObjectValue(cmb_ListFeePayYn) == 'E') {
            //fn_SaveAuto();

        }
    }
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == 'E') {
        cmb_ListFeePayYn.setDisabled(true);
        var vRsnCd = $c.stf.getObjectValue(cmb_BndListFeeExmptRsnCd);
        if (vRsnCd != '') {
            cmb_BndListFeeExmptRsnCd.setDisabled(true);
        }
    }
    edt_ListAmt.RightMargin = 5;
    edt_ListFee.RightMargin = 5;
    edt_ListFeeRepayAmt.RightMargin = 5;
};
scwin.img_ListFeeRepayDd_onclick = function() {
    if (dts_DtlInfo.getTotalRow() == 0) return;
    popUpCalendar2(edt_ListFeeRepayDd);
};
scwin.img_FeeDepoDd_onclick = function() {
    if (dts_DtlInfo.getTotalRow() == 0) return;
    popUpCalendar2(edt_FeeDepoDd);
};
scwin.cmb_ListFeePayYn_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == "E") {
        //상장수수료 면제사유 활성화
        cmb_BndListFeeExmptRsnCd.setDisabled(true);
        //상장수수료 금액 설정
        dts_DtlInfo.setCellData(1, "LIST_FEE", 0);
    } else {
        //상장수수료 면제사유 비활성화 및 초기화
        cmb_BndListFeeExmptRsnCd.setDisabled(true);
        $c.stf.setObjectValue(cmb_BndListFeeExmptRsnCd, '');
        //상장수수료 금액 설정
        dts_DtlInfo.setCellData(1, "LIST_FEE", 300000);
    }
};
scwin.btn_Save_onclick = async function() {
    if (dts_DtlInfo.getTotalRow() == 0) return;
    //필수 입력 값 체크
    if (scwin.fn_InputCheck() == false) return;
    scwin.fn_SaveAuto();
    if (scwin.objParam.MKTACT_TP_CD == '') {
        var arrPar = new Array();
        arrPar[0] = {
            REG_YN: "Y"
        };
        scwin.fn_SetPar(arrPar);
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    dts_DtlInfo.Reset();
    var arrPar = new Array();
    arrPar[0] = {
        REG_YN: "Y"
    };
    scwin.fn_SetPar(arrPar);
};
scwin.edt_ListAmt_OnKillFocus = function() {
    edt_ListAmt.RightMargin = 5;
};
scwin.edt_ListFee_OnKillFocus = function() {
    edt_ListFee.RightMargin = 5;
};
scwin.edt_ListFeeRepayAmt_OnKillFocus = function() {
    edt_ListFeeRepayAmt.RightMargin = 5;
};
